const R=1.0;

// ── Shader helpers ────────────────────────────────────────────────────────────
function compileShader(type,src){
  const s=gl.createShader(type);
  gl.shaderSource(s,src);gl.compileShader(s);
  if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))console.error(gl.getShaderInfoLog(s));
  return s;
}
function createProgram(vsSrc,fsSrc){
  const p=gl.createProgram();
  gl.attachShader(p,compileShader(gl.VERTEX_SHADER,vsSrc));
  gl.attachShader(p,compileShader(gl.FRAGMENT_SHADER,fsSrc));
  gl.linkProgram(p);
  if(!gl.getProgramParameter(p,gl.LINK_STATUS))console.error(gl.getProgramInfoLog(p));
  return p;
}

// ── Geometry generators ───────────────────────────────────────────────────────
function makeSphereGeo(r,wSeg,hSeg){
  const positions=[],normals=[],indices=[];
  for(let iy=0;iy<=hSeg;iy++){
    const v=iy/hSeg;
    for(let ix=0;ix<=wSeg;ix++){
      const u=ix/wSeg;
      const x=-r*Math.cos(u*2*Math.PI)*Math.sin(v*Math.PI);
      const y=r*Math.cos(v*Math.PI);
      const z=r*Math.sin(u*2*Math.PI)*Math.sin(v*Math.PI);
      positions.push(x,y,z);
      const nl=Math.sqrt(x*x+y*y+z*z);
      normals.push(x/nl,y/nl,z/nl);
    }
  }
  for(let iy=0;iy<hSeg;iy++){
    for(let ix=0;ix<wSeg;ix++){
      const a=iy*(wSeg+1)+ix,b=a+wSeg+1;
      indices.push(a,b,a+1,b,b+1,a+1);
    }
  }
  return{positions:new Float32Array(positions),normals:new Float32Array(normals),indices:new Uint16Array(indices)};
}

function makeRingGeo(inner,outer,seg){
  const positions=[],indices=[];
  for(let i=0;i<=seg;i++){
    const a=i/seg*2*Math.PI,cx=Math.cos(a),sy2=Math.sin(a);
    positions.push(inner*cx,inner*sy2,0);
    positions.push(outer*cx,outer*sy2,0);
  }
  for(let i=0;i<seg;i++){
    const a=i*2,b=a+1,c=a+2,d=a+3;
    indices.push(a,b,c,b,d,c);
  }
  return{positions:new Float32Array(positions),indices:new Uint16Array(indices)};
}

// ── VBO helpers ───────────────────────────────────────────────────────────────
function makeVBO(data){
  const buf=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);
  return buf;
}
function makeIBO(data){
  const buf=gl.createBuffer();
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,buf);
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,data,gl.STATIC_DRAW);
  return buf;
}

