// ── Globe program ─────────────────────────────────────────────────────────────
const globeVS=`
precision highp float;
attribute vec3 position;
attribute vec3 normal;
uniform mat4 projectionMatrix;
uniform mat4 modelViewMatrix;
uniform mat3 normalMatrix;
varying vec3 vNormal, vViewPos;
void main() {
  vNormal  = normalize(normalMatrix * normal);
  vec4 mp  = modelViewMatrix * vec4(position,1.0);
  vViewPos = -mp.xyz;
  gl_Position = projectionMatrix * mp;
}`;

const globeFS=`
      uniform float uDark;
      uniform float uVolume;
      varying vec3 vNormal, vViewPos;
      void main() {
        float NdotV  = clamp(dot(normalize(vNormal), normalize(vViewPos)), 0.0, 1.0);
        vec3  cL     = vec3(0.961, 0.961, 0.961);
        vec3  cD     = vec3(0.10,  0.12,  0.22 );
        vec3  color  = mix(cL, cD, uDark);

        // Horizonte: toque sutil de #434CE4 na borda da esfera (light mode)
        float fresnel = pow(1.0 - NdotV, 3.0);
        color = mix(color, vec3(0.263, 0.298, 0.894), fresnel * 0.20 * (1.0 - uDark));

        float aL     = pow(NdotV, 0.85) * 0.30;
        float aD     = pow(NdotV, 0.60) * 0.45;
        float alpha  = mix(aL, aD, uDark);

        // Volume: dois ângulos verticais (cima + baixo), laterais quase transparentes
        float diffUp   = max(dot(normalize(vNormal), normalize(vec3(0.0,  1.0, 0.3))), 0.0);
        float diffDown = max(dot(normalize(vNormal), normalize(vec3(0.0, -1.0, 0.3))), 0.0);
        float diff     = max(diffUp, diffDown);
        float lit      = pow(NdotV, 0.5) * 0.22 + diff * 0.16;
        float shad     = diff;
        alpha = mix(alpha, min(alpha * shad + lit, 0.32), uVolume * (1.0 - uDark));

        gl_FragColor = vec4(color, alpha);
      }`;

const globeProg=createProgram(globeVS,'precision highp float;\n'+globeFS);
const globeLoc={
  proj:    gl.getUniformLocation(globeProg,'projectionMatrix'),
  mv:      gl.getUniformLocation(globeProg,'modelViewMatrix'),
  nm:      gl.getUniformLocation(globeProg,'normalMatrix'),
  uDark:   gl.getUniformLocation(globeProg,'uDark'),
  uVolume: gl.getUniformLocation(globeProg,'uVolume'),
  position:gl.getAttribLocation(globeProg,'position'),
  normal:  gl.getAttribLocation(globeProg,'normal'),
};

// Build globe sphere buffers
const _gSph=makeSphereGeo(R,64,64);
const globePosBuf=makeVBO(_gSph.positions);
const globeNrmBuf=makeVBO(_gSph.normals);
const globeIdxBuf=makeIBO(_gSph.indices);
const globeIdxCount=_gSph.indices.length;
const globeUniforms={uDark:0.0,uVolume:0.0};

// ── Dot program ───────────────────────────────────────────────────────────────
const dotVS=`
precision highp float;
attribute vec3 position;
attribute float aSize;
uniform mat4 modelMatrix;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
uniform vec3 cameraPosition;
uniform float uSize;
varying float vFresnel;
void main() {
  vec3 wPos  = (modelMatrix*vec4(position,1.0)).xyz;
  vec3 vDir  = normalize(cameraPosition - wPos);
  float NdV  = clamp(dot(normalize(wPos), vDir), 0.0, 1.0);
  vFresnel   = 1.0 - NdV;
  vec4 mv    = modelViewMatrix*vec4(position,1.0);
  gl_PointSize = aSize * (uSize / 1.7);
  gl_Position  = projectionMatrix*mv;
}`;

const dotFS=`
          uniform float uDark;
          varying float vFresnel;
          void main() {
            if(length(gl_PointCoord-0.5)>0.5) discard;
            // #43B9E4 no centro, #434CE4 nas bordas (ambos os modos)
            vec3 cCenter = vec3(0.082, 0.635, 1.000);
            vec3 cEdge   = vec3(0.263, 0.298, 0.894);
            vec3 color   = mix(cCenter, cEdge, vFresnel);
            gl_FragColor=vec4(color, pow(1.0-vFresnel,1.6));
          }`;

const dotProg=createProgram(dotVS,'precision highp float;\n'+dotFS);
const dotLoc={
  modelMatrix:      gl.getUniformLocation(dotProg,'modelMatrix'),
  modelViewMatrix:  gl.getUniformLocation(dotProg,'modelViewMatrix'),
  projectionMatrix: gl.getUniformLocation(dotProg,'projectionMatrix'),
  cameraPosition:   gl.getUniformLocation(dotProg,'cameraPosition'),
  uSize:            gl.getUniformLocation(dotProg,'uSize'),
  uDark:            gl.getUniformLocation(dotProg,'uDark'),
  position:         gl.getAttribLocation(dotProg,'position'),
  aSize:            gl.getAttribLocation(dotProg,'aSize'),
};

// ── Solid color program (markers, rings, arcs) ────────────────────────────────
const solidVS=`
precision highp float;
attribute vec3 position;
uniform mat4 uMVP;
void main(){gl_Position=uMVP*vec4(position,1.0);}`;

const solidFS=`
precision highp float;
uniform vec4 uColor;
void main(){gl_FragColor=uColor;}`;

const solidProg=createProgram(solidVS,solidFS);
const solidLoc={
  uMVP:     gl.getUniformLocation(solidProg,'uMVP'),
  uColor:   gl.getUniformLocation(solidProg,'uColor'),
  position: gl.getAttribLocation(solidProg,'position'),
};

// ══════════════════════════════════════════════════════════════════════════════
// TOPOJSON DECODER  (replaces topojson.feature)
// ══════════════════════════════════════════════════════════════════════════════
function topoFeature(topology,object){
  const transform=topology.transform;
  const scale=transform?transform.scale:[1,1];
  const translate=transform?transform.translate:[0,0];
  function decodeArc(arcIdx){
    const negate=arcIdx<0;
    const raw=topology.arcs[negate?~arcIdx:arcIdx];
    let x=0,y=0;
    const coords=raw.map(pt=>{x+=pt[0];y+=pt[1];return[x*scale[0]+translate[0],y*scale[1]+translate[1]];});
    return negate?coords.reverse():coords;
  }
  function arcs(rings){return rings.map(ring=>ring.flatMap(decodeArc));}
  function geom(g){
    if(!g)return null;
    if(g.type==='GeometryCollection')return{type:'GeometryCollection',geometries:g.geometries.map(geom)};
    if(g.type==='Polygon')return{type:'Polygon',coordinates:arcs(g.arcs)};
    if(g.type==='MultiPolygon')return{type:'MultiPolygon',coordinates:g.arcs.map(arcs)};
    return null;
  }
  const geo=geom(object);
  const features=geo.type==='GeometryCollection'
    ?geo.geometries.map(g=>({type:'Feature',geometry:g}))
    :[{type:'Feature',geometry:geo}];
  return{type:'FeatureCollection',features};
}

// ══════════════════════════════════════════════════════════════════════════════
// GEOJSON CANVAS RENDERER  (replaces d3.geoPath + equirectangular projection)
// ══════════════════════════════════════════════════════════════════════════════
function drawGeoJSON(ctx,geojson,CW,CH){
  function projectCoord([lon,lat]){
    return[(lon+180)/360*CW,(90-lat)/180*CH];
  }
  function drawRing(coords){
    if(!coords.length)return;
    let[px,py]=projectCoord(coords[0]);
    ctx.moveTo(px,py);
    for(let i=1;i<coords.length;i++){
      const[nx,ny]=projectCoord(coords[i]);
      // Antimeridian: salto > metade do canvas = cruzamento de ±180°, levanta caneta
      if(Math.abs(nx-px)>CW/2){ctx.moveTo(nx,ny);}
      else{ctx.lineTo(nx,ny);}
      px=nx; py=ny;
    }
    ctx.closePath();
  }
  function drawGeometry(geom){
    if(!geom)return;
    if(geom.type==='Polygon')geom.coordinates.forEach(drawRing);
    else if(geom.type==='MultiPolygon')geom.coordinates.forEach(poly=>poly.forEach(drawRing));
    else if(geom.type==='GeometryCollection')geom.geometries.forEach(drawGeometry);
  }
  ctx.beginPath();
  if(geojson.type==='FeatureCollection')geojson.features.forEach(f=>drawGeometry(f.geometry));
  else if(geojson.type==='Feature')drawGeometry(geojson.geometry);
  else drawGeometry(geojson);
  ctx.fill('evenodd');
}

// ── Helper ────────────────────────────────────────────────────────────────────
function latLonToVec3(lat,lon,r){
  const la=lat*Math.PI/180,lo=lon*Math.PI/180;
  return new Vec3(r*Math.cos(la)*Math.sin(lo),r*Math.sin(la),r*Math.cos(la)*Math.cos(lo));
}

// ── Land dots (async) ─────────────────────────────────────────────────────────
let dotDrawable=null;
Promise.resolve(__GLOBE_TOPOLOGY__)
  .then(world=>{
    const CW=2048,CH=1024;
    const lc=document.createElement('canvas');lc.width=CW;lc.height=CH;
    const ctx=lc.getContext('2d');
    ctx.fillStyle='#000';ctx.fillRect(0,0,CW,CH);
    ctx.fillStyle='#fff';
    drawGeoJSON(ctx,topoFeature(world,world.objects.land),CW,CH);
    const px=ctx.getImageData(0,0,CW,CH).data;
    const isLand=(lat,lon)=>{
      const x=Math.min(Math.floor((lon+180)/360*CW),CW-1);
      const y=Math.min(Math.floor((90-lat)/180*CH),CH-1);
      return px[(y*CW+x)*4]>128;
    };
    const isCoastal=(lat,lon,r=4)=>{
      const cx=Math.min(Math.floor((lon+180)/360*CW),CW-1);
      const cy=Math.min(Math.floor((90-lat)/180*CH),CH-1);
      for(let dx=-r;dx<=r;dx++){
        for(let dy=-r;dy<=r;dy++){
          const nx=Math.min(Math.max(cx+dx,0),CW-1);
          const ny=Math.min(Math.max(cy+dy,0),CH-1);
          if(px[(ny*CW+nx)*4]<=128)return true;
        }
      }
      return false;
    };
    const latStep=0.38,buf=[],sizeBuf=[];
    const coastSizes=[1.8,1.9];
    const subSizes=[1.7,1.8,1.9];
    const interiorSizes=[1.6,1.7,1.8];
    for(let lat=-89.5;lat<=89.5;lat+=latStep){
      const ls=latStep/Math.max(Math.cos(lat*Math.PI/180),0.08);
      for(let lon=-180;lon<180;lon+=ls){
        if(!isLand(lat,lon))continue;
        const coast=isCoastal(lat,lon,4);
        const sub=!coast&&isCoastal(lat,lon,10);
        const prob=coast?0.87:sub?0.78:0.50;
        if(Math.random()<prob){
          const v=latLonToVec3(lat,lon,R*1.001);
          buf.push(v.x,v.y,v.z);
          const pool=coast?coastSizes:sub?subSizes:interiorSizes;
          sizeBuf.push(pool[Math.floor(Math.random()*pool.length)]);
        }
      }
    }
    dotDrawable={
      posBuf: makeVBO(new Float32Array(buf)),
      sizeBuf: makeVBO(new Float32Array(sizeBuf)),
      count: buf.length/3,
      uDark: 0.0,
      uSize: 1.7*DPR,
    };
  })
  .catch(()=>console.warn('world-atlas load failed'));

